BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE TABLE "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "twoFactorEnabled" boolean NOT NULL DEFAULT false);
CREATE TABLE session (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX session_user_id ON session("userId");
CREATE TABLE account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE("providerId","accountId"));
CREATE TABLE verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz DEFAULT now(), "updatedAt" timestamptz DEFAULT now());
CREATE INDEX verification_identifier ON verification(identifier);
CREATE TABLE "twoFactor" (id text PRIMARY KEY, secret text NOT NULL, "backupCodes" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, verified boolean DEFAULT false);
CREATE TABLE auth_stepups (session_id text PRIMARY KEY REFERENCES session(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES "user"(id), expires_at timestamptz NOT NULL);
CREATE TABLE admin_bootstrap (id boolean PRIMARY KEY DEFAULT true CHECK(id), user_id text NOT NULL REFERENCES "user"(id), completed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE libraries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id text UNIQUE, name text NOT NULL, display_name text NOT NULL, aliases text[] NOT NULL DEFAULT '{}', country_code char(2) NOT NULL CHECK(country_code ~ '^[A-Z]{2}$'), region text, latitude double precision CHECK(latitude BETWEEN -90 AND 90), longitude double precision CHECK(longitude BETWEEN -180 AND 180), population bigint CHECK(population>0), population_year int, population_definition text, source_url text, rank int UNIQUE CHECK(rank BETWEEN 1 AND 50), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX libraries_canonical ON libraries(country_code,lower(name),coalesce(lower(region),''));
CREATE TABLE members (id text PRIMARY KEY REFERENCES "user"(id), display_name text NOT NULL, handle text UNIQUE NOT NULL CHECK(handle ~ '^[a-z0-9_]{3,32}$'), role text NOT NULL DEFAULT 'MEMBER' CHECK(role IN ('MEMBER','MODERATOR','ADMIN')), status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','SUSPENDED','DELETION_PENDING','DELETED')), adult boolean NOT NULL DEFAULT false, home_library_id uuid REFERENCES libraries(id), bio text NOT NULL DEFAULT '' CHECK(length(bio)<=500), icon text NOT NULL DEFAULT 'book' CHECK(icon IN ('book','leaf','owl','fox','cat','moon','sun','star','flower','tree','mountain','coffee','lamp','feather','quill','glasses','boat','compass','key','bee','butterfly','hedgehog','acorn','shell','candle','cloud','planet','mushroom','lighthouse','rabbit','cherry','kite')), public_collection boolean NOT NULL DEFAULT false, public_stats boolean NOT NULL DEFAULT false, leaderboard_opt_in boolean NOT NULL DEFAULT false, email_optional boolean NOT NULL DEFAULT false, bookshelf_paused boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moderator_scopes (member_id text NOT NULL REFERENCES members(id), library_id uuid REFERENCES libraries(id), global_scope boolean NOT NULL DEFAULT false, CHECK(global_scope OR library_id IS NOT NULL), UNIQUE NULLS NOT DISTINCT(member_id,library_id));
CREATE TABLE library_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requester_id text NOT NULL REFERENCES members(id), country_code char(2) NOT NULL, locality text NOT NULL, locality_key text NOT NULL, region text NOT NULL DEFAULT '', explanation text NOT NULL CHECK(length(explanation)<=1500), state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','APPROVED','REJECTED','LINKED')), library_id uuid REFERENCES libraries(id), reason text, created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz);
CREATE UNIQUE INDEX pending_library_request ON library_requests(country_code,locality_key,lower(region)) WHERE state='PENDING';
CREATE TABLE works (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 300), authors text[] NOT NULL CHECK(cardinality(authors) BETWEEN 1 AND 12), title_key text NOT NULL, author_key text NOT NULL, search_key text NOT NULL, kind text NOT NULL DEFAULT 'original' CHECK(kind IN ('original','adaptation','anthology','volume')), volume_key text NOT NULL DEFAULT '', genre text NOT NULL DEFAULT 'Literatură', audience text NOT NULL DEFAULT 'adults' CHECK(audience IN ('adults','children','young-adult','all')), description text NOT NULL DEFAULT '' CHECK(length(description)<=4000), merged_into uuid REFERENCES works(id), moderation_state text NOT NULL DEFAULT 'APPROVED' CHECK(moderation_state IN ('APPROVED','PENDING','HIDDEN')), created_by text REFERENCES members(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(title_key,author_key,kind,volume_key));
CREATE INDEX work_search_trgm ON works USING gin(search_key gin_trgm_ops);
CREATE TABLE work_aliases (work_id uuid NOT NULL REFERENCES works(id), alias text NOT NULL, alias_key text NOT NULL, PRIMARY KEY(work_id,alias_key));
CREATE INDEX work_alias_search ON work_aliases USING gin(alias_key gin_trgm_ops);
CREATE TABLE editions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_id uuid NOT NULL REFERENCES works(id), language text NOT NULL DEFAULT 'ro' CHECK(language IN ('ro','ro-bilingual')), publisher text, year int CHECK(year BETWEEN 1400 AND 2200), isbn text UNIQUE CHECK(isbn IS NULL OR isbn ~ '^[0-9]{13}$'), translator text, volume text, abridged boolean, unspecified boolean NOT NULL DEFAULT false, fingerprint text NOT NULL, provenance jsonb NOT NULL DEFAULT '{}', cover_key text, cover_state text NOT NULL DEFAULT 'NONE' CHECK(cover_state IN ('NONE','PENDING','APPROVED','REJECTED')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(work_id,fingerprint));
CREATE INDEX editions_work ON editions(work_id);
CREATE TABLE copies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), edition_id uuid NOT NULL REFERENCES editions(id), owner_id text NOT NULL REFERENCES members(id), library_id uuid NOT NULL REFERENCES libraries(id), condition text NOT NULL CHECK(condition IN ('new','good','fair','worn')), notes text NOT NULL DEFAULT '' CHECK(length(notes)<=1000), collection_note text NOT NULL DEFAULT '' CHECK(length(collection_note)<=300), visibility text NOT NULL DEFAULT 'PRIVATE' CHECK(visibility IN ('PUBLIC','PRIVATE')), state text NOT NULL DEFAULT 'AVAILABLE' CHECK(state IN ('AVAILABLE','PAUSED','RESERVED','ON_LOAN','RETURN_PENDING','DISPUTED','LOST','REMOVED')), max_days int CHECK(max_days BETWEEN 1 AND 180), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX copies_catalogue ON copies(library_id,edition_id,state) WHERE visibility='PUBLIC';
CREATE INDEX copies_owner ON copies(owner_id);
CREATE TABLE copy_photos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), copy_id uuid NOT NULL REFERENCES copies(id), owner_id text NOT NULL REFERENCES members(id), storage_key text NOT NULL UNIQUE, bytes bigint NOT NULL CHECK(bytes>=0), widths int[] NOT NULL, state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','APPROVED','REJECTED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ownership_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), copy_id uuid NOT NULL REFERENCES copies(id), previous_owner text REFERENCES members(id), new_owner text NOT NULL REFERENCES members(id), reason text NOT NULL CHECK(reason IN ('LISTED','DONATED')), loan_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE loan_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), copy_id uuid NOT NULL REFERENCES copies(id), borrower_id text NOT NULL REFERENCES members(id), lender_id text NOT NULL REFERENCES members(id), library_id uuid NOT NULL REFERENCES libraries(id), state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','ACCEPTED','DECLINED','CANCELLED','EXPIRED')), message text NOT NULL DEFAULT '' CHECK(length(message)<=1500), created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz, CHECK(lender_id<>borrower_id));
CREATE UNIQUE INDEX pending_copy_borrower ON loan_requests(copy_id,borrower_id) WHERE state='PENDING';
CREATE TABLE loans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL UNIQUE REFERENCES loan_requests(id), copy_id uuid NOT NULL REFERENCES copies(id), lender_id text NOT NULL REFERENCES members(id), borrower_id text NOT NULL REFERENCES members(id), library_id uuid NOT NULL REFERENCES libraries(id), state text NOT NULL DEFAULT 'RESERVED' CHECK(state IN ('RESERVED','ON_LOAN','RETURN_PENDING','RETURNED','DONATED','CANCELLED','EXPIRED','DISPUTED','LOST')), duration_days int NOT NULL CHECK(duration_days BETWEEN 1 AND 180), reserved_until timestamptz NOT NULL, handed_over_at timestamptz, handover_actor text REFERENCES members(id), acknowledged_at timestamptz, original_due_at timestamptz, due_at timestamptz, borrower_return_at timestamptz, returned_at timestamptz, return_actor text REFERENCES members(id), closed_at timestamptz, resolution_reason text, created_at timestamptz NOT NULL DEFAULT now(), CHECK(lender_id<>borrower_id), CHECK(state NOT IN ('ON_LOAN','RETURN_PENDING','RETURNED','DONATED') OR handed_over_at IS NOT NULL), CHECK((handed_over_at IS NULL AND handover_actor IS NULL AND due_at IS NULL) OR (handed_over_at IS NOT NULL AND handover_actor IS NOT NULL AND handover_actor=lender_id AND due_at IS NOT NULL AND original_due_at IS NOT NULL)), CHECK(state<>'RETURNED' OR (returned_at IS NOT NULL AND return_actor IS NOT NULL AND return_actor=lender_id)));
CREATE UNIQUE INDEX one_active_copy ON loans(copy_id) WHERE state IN ('RESERVED','ON_LOAN','RETURN_PENDING','DISPUTED','LOST');
CREATE INDEX loans_due ON loans(due_at) WHERE state IN ('ON_LOAN','RETURN_PENDING');
ALTER TABLE ownership_history ADD CONSTRAINT ownership_loan_fk FOREIGN KEY(loan_id) REFERENCES loans(id);
CREATE TABLE loan_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), loan_id uuid NOT NULL REFERENCES loans(id), actor_id text REFERENCES members(id), event text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE extensions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), loan_id uuid NOT NULL REFERENCES loans(id), requested_by text NOT NULL REFERENCES members(id), days int NOT NULL CHECK(days BETWEEN 1 AND 90), state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','APPROVED','DECLINED')), previous_due_at timestamptz, new_due_at timestamptz, approved_by text REFERENCES members(id), created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz);
CREATE UNIQUE INDEX pending_extension ON extensions(loan_id) WHERE state='PENDING';
CREATE TABLE gift_offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), loan_id uuid NOT NULL REFERENCES loans(id), donor_id text NOT NULL REFERENCES members(id), recipient_id text NOT NULL REFERENCES members(id), state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','ACCEPTED','DECLINED','CANCELLED')), created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz);
CREATE UNIQUE INDEX pending_gift ON gift_offers(loan_id) WHERE state='PENDING';
CREATE UNIQUE INDEX accepted_gift ON gift_offers(loan_id) WHERE state='ACCEPTED';
CREATE TABLE blocks (blocker_id text NOT NULL REFERENCES members(id), blocked_id text NOT NULL REFERENCES members(id), created_at timestamptz NOT NULL DEFAULT now(), CHECK(blocker_id<>blocked_id), PRIMARY KEY(blocker_id,blocked_id));
CREATE TABLE conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), member_a text NOT NULL REFERENCES members(id), member_b text NOT NULL REFERENCES members(id), loan_id uuid UNIQUE REFERENCES loans(id), state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','ACCEPTED','DECLINED')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(member_a<>member_b));
CREATE UNIQUE INDEX conversation_contact ON conversations(least(member_a,member_b),greatest(member_a,member_b)) WHERE loan_id IS NULL AND state<>'DECLINED';
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id), sender_id text NOT NULL REFERENCES members(id), body text NOT NULL CHECK(length(body) BETWEEN 1 AND 3000), client_key uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(sender_id,client_key));
CREATE INDEX message_conversation_time ON messages(conversation_id,created_at DESC);
CREATE TABLE conversation_reads (conversation_id uuid NOT NULL REFERENCES conversations(id), member_id text NOT NULL REFERENCES members(id), read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(conversation_id,member_id));
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), member_id text NOT NULL REFERENCES members(id), type text NOT NULL, title text NOT NULL, href text NOT NULL, dedupe_key text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(member_id,dedupe_key));
CREATE TABLE notification_preferences (member_id text NOT NULL REFERENCES members(id), category text NOT NULL, in_app boolean NOT NULL DEFAULT true, email boolean NOT NULL DEFAULT false, PRIMARY KEY(member_id,category));
CREATE TABLE book_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_id uuid NOT NULL REFERENCES works(id), edition_id uuid REFERENCES editions(id), member_id text NOT NULL REFERENCES members(id), stars int NOT NULL CHECK(stars BETWEEN 1 AND 5), body text NOT NULL DEFAULT '' CHECK(length(body)<=3000), spoiler boolean NOT NULL DEFAULT false, state text NOT NULL DEFAULT 'VISIBLE' CHECK(state IN ('VISIBLE','HIDDEN','DELETED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(work_id,member_id));
CREATE TABLE member_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), loan_id uuid NOT NULL REFERENCES loans(id), reviewer_id text NOT NULL REFERENCES members(id), recipient_id text NOT NULL REFERENCES members(id), reviewer_role text NOT NULL CHECK(reviewer_role IN ('lender','borrower')), stars int NOT NULL CHECK(stars BETWEEN 1 AND 5), body text NOT NULL DEFAULT '' CHECK(length(body)<=3000), response text, response_state text NOT NULL DEFAULT 'NONE' CHECK(response_state IN ('NONE','PENDING','VISIBLE','HIDDEN')), publish_after timestamptz NOT NULL, published_at timestamptz, state text NOT NULL DEFAULT 'VISIBLE' CHECK(state IN ('VISIBLE','HIDDEN','DELETED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(loan_id,reviewer_id,recipient_id), CHECK(reviewer_id<>recipient_id));
CREATE TABLE reading_states (member_id text NOT NULL REFERENCES members(id), work_id uuid NOT NULL REFERENCES works(id), state text NOT NULL CHECK(state IN ('want','reading','finished','abandoned')), first_finished_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(member_id,work_id));
CREATE TABLE reading_goals (member_id text NOT NULL REFERENCES members(id), year int NOT NULL CHECK(year BETWEEN 2020 AND 2200), target int NOT NULL CHECK(target BETWEEN 1 AND 1000), PRIMARY KEY(member_id,year));
CREATE TABLE reward_events (loan_id uuid PRIMARY KEY REFERENCES loans(id), outcome text NOT NULL CHECK(outcome IN ('RETURNED','DONATED')), rule_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE xp_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), member_id text NOT NULL REFERENCES members(id), event_key text NOT NULL, reason text NOT NULL, points int NOT NULL, rule_version text NOT NULL, data jsonb NOT NULL DEFAULT '{}', actor_id text REFERENCES members(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(member_id,event_key,reason));
CREATE INDEX xp_member_time ON xp_ledger(member_id,created_at);
CREATE FUNCTION immutable_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Ledger is append-only'; END $$;
CREATE TRIGGER xp_append_only BEFORE UPDATE OR DELETE ON xp_ledger FOR EACH ROW EXECUTE FUNCTION immutable_ledger();
CREATE TABLE reward_flags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), member_id text NOT NULL REFERENCES members(id), loan_id uuid REFERENCES loans(id), reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE forum_categories (id text PRIMARY KEY, title text NOT NULL, description text NOT NULL DEFAULT '', sort_order int NOT NULL DEFAULT 0, announcement boolean NOT NULL DEFAULT false);
CREATE TABLE forum_topics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_id text NOT NULL REFERENCES forum_categories(id), library_id uuid REFERENCES libraries(id), author_id text NOT NULL REFERENCES members(id), title text NOT NULL CHECK(length(title) BETWEEN 3 AND 180), tags text[] NOT NULL DEFAULT '{}', pinned boolean NOT NULL DEFAULT false, locked boolean NOT NULL DEFAULT false, state text NOT NULL DEFAULT 'VISIBLE' CHECK(state IN ('VISIBLE','HIDDEN','DELETED')), merged_into uuid REFERENCES forum_topics(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX forum_topic_title ON forum_topics USING gin(title gin_trgm_ops);
CREATE TABLE forum_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic_id uuid NOT NULL REFERENCES forum_topics(id), author_id text NOT NULL REFERENCES members(id), body text NOT NULL CHECK(length(body)<=10000), quoted_post_id uuid REFERENCES forum_posts(id), state text NOT NULL DEFAULT 'VISIBLE' CHECK(state IN ('VISIBLE','HIDDEN','DELETED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX forum_post_topic ON forum_posts(topic_id,created_at);
CREATE TABLE post_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES forum_posts(id), actor_id text NOT NULL REFERENCES members(id), old_body text NOT NULL, reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE forum_reactions (post_id uuid NOT NULL REFERENCES forum_posts(id), member_id text NOT NULL REFERENCES members(id), PRIMARY KEY(post_id,member_id));
CREATE TABLE topic_preferences (topic_id uuid NOT NULL REFERENCES forum_topics(id), member_id text NOT NULL REFERENCES members(id), bookmarked boolean NOT NULL DEFAULT false, followed boolean NOT NULL DEFAULT false, read_at timestamptz, PRIMARY KEY(topic_id,member_id));
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id text REFERENCES members(id), public_contact text, target_type text NOT NULL CHECK(target_type IN ('message','work','edition','copy','photo','member','member_review','book_review','topic','post','loan')), target_id text NOT NULL, category text NOT NULL CHECK(category IN ('harassment','threat','scam','spam','privacy','metadata','duplicate','prohibited','other')), explanation text NOT NULL CHECK(length(explanation) BETWEEN 10 AND 3000), library_id uuid REFERENCES libraries(id), evidence jsonb NOT NULL DEFAULT '{}', state text NOT NULL DEFAULT 'RECEIVED' CHECK(state IN ('RECEIVED','TRIAGED','INVESTIGATING','RESOLVED','DISMISSED','APPEAL_REQUESTED','APPEAL_RESOLVED')), decision text, appeal text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moderation_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid REFERENCES reports(id), actor_id text NOT NULL REFERENCES members(id), action text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id text REFERENCES members(id), action text NOT NULL, target_type text NOT NULL, target_id text, reason text, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE legal_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL, version int NOT NULL, title text NOT NULL, body text NOT NULL, is_draft boolean NOT NULL DEFAULT true, published_at timestamptz, created_by text REFERENCES members(id), UNIQUE(slug,version));
CREATE TABLE legal_acceptances (member_id text NOT NULL REFERENCES members(id), document_id uuid NOT NULL REFERENCES legal_documents(id), accepted_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(member_id,document_id));
CREATE TABLE privacy_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), member_id text NOT NULL REFERENCES members(id), kind text NOT NULL CHECK(kind IN ('EXPORT','DELETE','CORRECTION')), explanation text NOT NULL DEFAULT '', state text NOT NULL DEFAULT 'RECEIVED' CHECK(state IN ('RECEIVED','REVIEWING','COMPLETED','REFUSED')), reason text, requested_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type text NOT NULL, dedupe_key text NOT NULL UNIQUE, payload jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','RUNNING','DONE','FAILED','CANCELLED')), attempts int NOT NULL DEFAULT 0, run_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_pending ON jobs(run_at) WHERE status='PENDING';
CREATE TABLE rate_limits (key text PRIMARY KEY, count int NOT NULL, window_start timestamptz NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE metadata_cache (key text PRIMARY KEY, provider text NOT NULL, payload jsonb NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE ad_preview_sessions (session_id text PRIMARY KEY REFERENCES session(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE user_consents (member_id text NOT NULL REFERENCES members(id), purpose text NOT NULL, granted boolean NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(member_id,purpose));
COMMIT;
